head.script:
scwin.trigger1_onclick = function(e) {
    dataList1.insertColumn("col1", {
        "name": "column1",
        "dataType": "text"
    }); //동적으로 컬럼추가 
    //alert(dataList1.getTotalCol()); 
    log = dataList1.getTotalCol();
};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 웹스퀘어에서 빈 xml 을 생성한다.
    //1. Create a blank xml in WebSquare.
    //Verify step 1. xml is created.
    //Test step 2. Component 창에서 head -> Model -> DataCollection 에서 마우스 오른쪽 -> DataList 를 클릭한다.
    //2. In the Component window, head -> Model -> DataCollection, right -> DataList.
    //Verify step 2. A data list is created.
    //Test step 3. 브라우저에서 insertColumn 버튼을 클릭한다. 
    //3. In the browser, click the insertColumn button.
    //Verify step 3. Pop-up the number of generated columns.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log == '1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined;
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 02-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
